insert into public.hero_slides(key,label_fr,label_ar,data,sort_order,is_active) values ('voyageurs','Vos déplacements, notre engagement.','تنقلاتكم، التزامنا.','{"label_fr":"TRANSPORT DE VOYAGEURS","label_ar":"نقل المسافرين","body_fr":"Découvrez les services SLKM pour vos déplacements et vos besoins en transport.","body_ar":"اكتشفوا خدمات SLKM لتلبية احتياجاتكم في التنقل والنقل.","image":"","media_key":"coaches","focal":"50% 50%","mobile_focal":"50% 50%","cta_fr":"Découvrir notre réseau","cta_ar":"اكتشفوا شبكتنا","href":"#reseau","secondary_cta_fr":"Nous contacter","secondary_cta_ar":"تواصلوا معنا","secondary_href":"#contact"}'::jsonb,0,true) on conflict(key) do nothing;
insert into public.hero_slides(key,label_fr,label_ar,data,sort_order,is_active) values ('minibus','Des solutions pour vos équipes et vos voyages.','حلول لتنقل فرق العمل ورحلاتكم.','{"label_fr":"PERSONNEL & TOURISME","label_ar":"نقل المستخدمين والنقل السياحي","body_fr":"Des véhicules adaptés aux déplacements de vos équipes et à vos projets de voyage.","body_ar":"مركبات تناسب تنقل فرق العمل ومشاريع رحلاتكم.","image":"","media_key":"minibuses","cta_fr":"Explorer nos transports","cta_ar":"اكتشفوا خدمات النقل","href":"#transports","secondary_cta_fr":"Nous contacter","secondary_cta_ar":"تواصلوا معنا","secondary_href":"#contact"}'::jsonb,1,true) on conflict(key) do nothing;
insert into public.hero_slides(key,label_fr,label_ar,data,sort_order,is_active) values ('bennes','Des moyens adaptés à vos projets.','وسائل نقل تناسب مشاريعكم.','{"label_fr":"LOCATION & LOGISTIQUE","label_ar":"الكراء والخدمات اللوجستية","body_fr":"Camions-bennes et remorques-bennes : échangeons sur vos besoins.","body_ar":"شاحنات ومقطورات قلابة: تواصلوا معنا لمناقشة احتياجاتكم.","image":"","media_key":"trucks","cta_fr":"Parlons de votre projet","cta_ar":"لنتحدث عن مشروعكم","href":"#contact","secondary_cta_fr":"Nous contacter","secondary_cta_ar":"تواصلوا معنا","secondary_href":"#contact"}'::jsonb,2,true) on conflict(key) do nothing;
insert into public.page_sections(key,label_fr,label_ar,data,sort_order,is_active) values ('histoire','Le transport, une affaire de proximité.','النقل، التزام بالقرب منكم.','{"eyebrow_fr":"DÉCOUVRIR SLKM","eyebrow_ar":"تعرّفوا على SLKM","body_fr":"SLKM accompagne les particuliers et les professionnels dans leurs besoins de transport. Transport de voyageurs, messagerie, transport du personnel, déplacements touristiques et location de camions-bennes : découvrez des services adaptés à différents usages.","body_ar":"تواكب SLKM الأفراد والمهنيين في احتياجاتهم في النقل. نقل المسافرين والطرود والمستخدمين، والرحلات السياحية وكراء الشاحنات القلابة: خدمات تناسب استخدامات متنوعة.","second_fr":"Notre engagement : être à votre écoute et vous orienter vers une solution adaptée à votre besoin.","second_ar":"التزامنا: الإصغاء إليكم وتوجيهكم نحو حل يناسب احتياجاتكم.","image":"","media_key":"minibuses","values_fr":["Proximité","Confort","Qualité de service"],"values_ar":["القرب منكم","الراحة","جودة الخدمة"],"milestones_fr":[],"milestones_ar":[]}'::jsonb,0,true) on conflict(key) do nothing;
insert into public.page_sections(key,label_fr,label_ar,data,sort_order,is_active) values ('services','À chaque besoin, son transport.','لكل احتياج، خدمة نقل.','{"eyebrow_fr":"NOS EXPERTISES","eyebrow_ar":"خدماتنا"}'::jsonb,1,true) on conflict(key) do nothing;
insert into public.page_sections(key,label_fr,label_ar,data,sort_order,is_active) values ('reseau','Votre prochain trajet commence ici.','رحلتكم القادمة تبدأ من هنا.','{"eyebrow_fr":"LIGNES & RÉSEAU","eyebrow_ar":"الخطوط والشبكة","body_fr":"Retrouvez les informations sur le réseau de voyageurs SLKM. Notre équipe vous renseigne sur les lignes et horaires disponibles.","body_ar":"تعرّفوا على شبكة نقل المسافرين SLKM. فريقنا رهن إشارتكم للاستفسار عن الخطوط والمواعيد المتاحة."}'::jsonb,2,true) on conflict(key) do nothing;
insert into public.page_sections(key,label_fr,label_ar,data,sort_order,is_active) values ('messagerie','Vos colis, notre lien au quotidien.','طرودكم، صلتنا بكم كل يوم.','{"eyebrow_fr":"MESSAGERIE & MARCHANDISES","eyebrow_ar":"نقل الطرود والبضائع","body_fr":"Pour vos besoins d’envoi de colis et de marchandises, contactez SLKM afin de connaître les destinations desservies et les modalités de prise en charge.","body_ar":"لإرسال طرودكم وبضائعكم، تواصلوا مع SLKM لمعرفة الوجهات المتاحة وشروط التكفل بشحناتكم."}'::jsonb,3,true) on conflict(key) do nothing;
insert into public.page_sections(key,label_fr,label_ar,data,sort_order,is_active) values ('transports','Des véhicules pour chaque usage.','مركبات تناسب مختلف الاستخدامات.','{"eyebrow_fr":"FLOTTE & PRESTATIONS","eyebrow_ar":"المركبات وخدمات النقل","body_fr":"Les capacités ci-dessous décrivent les types de véhicules proposés, et non le nombre de véhicules de la flotte.","body_ar":"تشير السعات التالية إلى أنواع المركبات المقترحة، وليس إلى عدد مركبات الأسطول."}'::jsonb,4,true) on conflict(key) do nothing;
insert into public.page_sections(key,label_fr,label_ar,data,sort_order,is_active) values ('contact','Parlons de votre besoin.','لنتحدث عن احتياجاتكم.','{"eyebrow_fr":"RESTONS EN CONTACT","eyebrow_ar":"لنبقَ على تواصل","body_fr":"Un déplacement, un envoi ou un projet ? Notre équipe est à votre écoute.","body_ar":"تنقل أو إرسال طرد أو مشروع؟ فريقنا يصغي إليكم."}'::jsonb,5,true) on conflict(key) do nothing;
